    id text primary key,
    team_id text not null,
    scenario_id text not null default '',
    actor text not null,
    reason text not null default '',
    refused integer not null default 0,
    created_date double precision not null
);
create index if not exists holdout_access_crew on holdout_access (team_id, created_date);

-- v27: the seal's fingerprint. a seal nobody can check is a promise, not a wall: the
-- scenarios are rows, and rows can be edited between the claim and the gate. the digest is
-- taken over the criteria as sealed, so a later edit is visible instead of silent.
create table if not exists holdout_seals (
    team_id text primary key references teams(id) on delete cascade,
    digest text not null,
    scenarios integer not null default 0,
    actor text not null default 'owner',
    sealed_date double precision not null
);

-- a scored run, and whether it was clean when it was scored.
create table if not exists holdout_runs (
    id text primary key,
    team_id text not null,
    scenarios integer not null default 0,
    passed integer not null default 0,
    metric double precision not null default 0,
    clean integer not null default 1,
    access_during integer not null default 0,
    actor text not null default 'owner',
    created_date double precision not null
);

-- v30: the visible half of the criteria, and the gap between it and the sealed half. an agent
-- that can read its examples will fit them, so the number worth reading is the distance between
-- the examples it saw and the scenarios it did not.
create table if not exists holdout_public (
    id text primary key,
    team_id text not null,
    name text not null,
    input text not null,
    expect text not null,
    scorer text not null default '{"kind":"contains"}',
    created_date double precision not null
);
create index if not exists holdout_public_crew on holdout_public (team_id, created_date);

-- one gap run: both rates, the distance between them, and whether the work is acceptable.
-- a near miss is recorded as a number rather than rounded to a fail, which is the whole point
-- of grading partially.
create table if not exists holdout_gaps (
    id text primary key,
    team_id text not null,
    public_total integer not null default 0,
    public_passed integer not null default 0,
    holdout_total integer not null default 0,
    holdout_passed integer not null default 0,
    gap double precision,
    public_digest text not null default '',
    verdict text not null default 'thin',
    accepted integer not null default 0,
    clean integer not null default 1,
    reasons text not null default '[]',
    actor text not null default 'owner',
    created_date double precision not null
);
create index if not exists holdout_gaps_crew on holdout_gaps (team_id, created_date);

-- v31: the decisions a crew builds on, as rows. a statement is a claim with a kind, a subject,
-- a source and a decider, so work can be checked against it before it is done. the six kinds are
-- the six ways work drifts from the record, and none of them are about code in particular.
create table if not exists statements (
    id text primary key,
    team_id text not null,
    text text not null,
    drift text not null default 'logic',
    subject text not null default '',
    certainty text not null default 'provisional',
    source text not null default '',
    source_kind text not null default 'note',
    decided_by text not null default '',
    decided_by_kind text not null default 'person',
    contradicts text not null default '[]',
    supersedes text not null default '',
    status text not null default 'active',
    note text not null default '',
    digest text not null default '',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists statements_crew on statements (team_id, status, drift);
create index if not exists statements_subject on statements (team_id, subject);

-- every check is a row: what was asked, what the ledger said, and who asked. the answer is worth
-- less than the record that somebody asked before building.
create table if not exists statement_checks (
    id text primary key,
    team_id text not null,
    task_id text not null default '',
    subjects text not null default '[]',
    verdict text not null default 'clear',
    found text not null default '[]',
    actor text not null default '',
    created_date double precision not null
);
create index if not exists statement_checks_crew on statement_checks (team_id, created_date);

-- v32: what a run actually reached for, against what it was provisioned with. an advantage that
-- arrived through a channel nobody provisioned is real, and it is not reproducible, so a crew
-- that counts it at par with its own supply learns nothing about what the supply can produce.
create table if not exists readable_checks (
    id text primary key,
    team_id text not null,
    task_id text not null default '',
    run_id text not null default '',
    signals integer not null default 0,
    readable integer not null default 0,
    auxiliary integer not null default 0,
    unprovisioned integer not null default 0,
    why text not null default '[]',
    created_date double precision not null
);
create index if not exists readable_checks_crew on readable_checks (team_id, created_date);
create index if not exists readable_checks_run on readable_checks (run_id);

-- v36: an escalation is a decision put to a person, with the four lines and the default it takes
-- if nobody answers. a person answers it; the org takes the default and says so, as its own outcome.
create table if not exists escalations (
    id text primary key,
    team_id text not null,
    raised_by text not null references agents(id) on delete cascade,
    task_id text,
    category text not null,
    what_happened text not null,
    already_tried text not null,
    decision_needed text not null,
    default_action text not null,
    default_after double precision not null,
    state text not null default 'open',
    answer text,
    answered_by text,
    outcome text,
    month text not null,
    reached text not null default '[]',
    raised_date double precision not null,
    settled_date double precision
);
create index if not exists escalations_crew on escalations (team_id, state);
create index if not exists escalations_month on escalations (team_id, month);

-- v35: the second axis of an org chart. a surface has exactly one owning department; reaching into
-- another's is a proposal the owner settles; a bloc lends seats for one objective with an expiry;
-- a wing holds a veto in a domain and has nothing to grow.
create table if not exists org_surfaces (
    id text primary key,
    team_id text not null,
    name text not null,
    owner_department_id text not null references departments(id) on delete cascade,
    evidence text not null default '[]',
    purpose text not null default '',
    created_date double precision not null,
    unique (team_id, name)
);
create table if not exists org_proposals (
    id text primary key,
    team_id text not null,
    surface text not null,
    owner_department_id text not null,
    proposed_by text not null,
    task_id text,
    change text not null,
    state text not null default 'open',
    settled_by text,
    answer text,
    created_date double precision not null,
    settled_date double precision
);
create index if not exists org_proposals_crew on org_proposals (team_id, state);
create table if not exists org_blocs (
    id text primary key,
    team_id text not null,
    name text not null,
    objective text not null,
    department_ids text not null default '[]',
    state text not null default 'open',
    closes_at double precision not null,
    created_date double precision not null,
    closed_date double precision
);
create table if not exists org_bloc_grants (
    id text primary key,
    bloc_id text not null references org_blocs(id) on delete cascade,
    agent_id text not null references agents(id) on delete cascade,
    expires_at double precision not null,
    revoked_at double precision,
    created_date double precision not null
);
create index if not exists org_bloc_grants_agent on org_bloc_grants (agent_id, expires_at);
create table if not exists org_wings (
    id text primary key,
    team_id text not null,
    name text not null,
    domain text not null,
    agent_ids text not null default '[]',
    cadence text not null default '',
    created_date double precision not null,
    unique (team_id, domain)
);
create table if not exists org_vetoes (
    id text primary key,
    team_id text not null,
    wing_id text not null references org_wings(id) on delete cascade,
    task_id text not null,
    by_agent_id text not null,
    reason text not null,
    created_date double precision not null,
    lifted_date double precision,
    lifted_by text
);
create index if not exists org_vetoes_card on org_vetoes (task_id, lifted_date);

-- v34: a risk a person accepted, until a moment they named. a dismissal is not a deletion: the
-- finding is recomputed from rows every time, and a lapsed acceptance comes back naming whoever
-- gave it, because the second decision is theirs.
create table if not exists posture_dismissals (
    id text primary key,
    team_id text not null,
    finding_key text not null,
    severity text not null default 'low',
    owner text not null,
    reason text not null,
    until_date double precision not null,
    created_date double precision not null
);
create index if not exists posture_dismissals_crew on posture_dismissals (team_id, finding_key);

-- v33: what a card of a given kind owes before it may move, and the questions it still has open.
-- an open question is a record rather than a comment: it has an asker, it has an answer or a
-- reason it was dropped, and while it is open the card it belongs to is not reviewable.
create table if not exists questions (
    id text primary key,
    team_id text not null,
    task_id text not null default '',
    text text not null,
    asked_by text not null default '',
    status text not null default 'open',
    answer text not null default '',
    answered_by text not null default '',
    created_date double precision not null,
    closed_date double precision
);
create index if not exists questions_card on questions (task_id, status);
create index if not exists questions_crew on questions (team_id, status);

-- a waived phase is a person's decision, with a reason, and an agent may not make one
create table if not exists phase_waivers (
    id text primary key,
    team_id text not null,
    task_id text not null default '',
    column_name text not null,
    reason text not null,
    waived_by text not null default 'owner',
    created_date double precision not null
);
create index if not exists phase_waivers_card on phase_waivers (task_id, column_name);

-- v23: skills. a skill is know-how with a name and a trigger, loaded in three stages so a
-- crew with forty of them does not spend forty bodies of context on a card that needs none.
create table if not exists skills (
  id text primary key,
  team_id text not null,
  name text not null,
  description text not null,
  body text not null default '',
  allowed_tools text not null default '[]',
  metadata text not null default '{}',
  license text not null default '',
  -- addressed to nobody is addressed to everyone: an empty list means the whole crew
  agents text not null default '[]',
  origin text not null default 'authored',
  source text not null default '',
  enabled integer not null default 1,
  body_chars integer not null default 0,
  created_date double precision not null,
  updated_date double precision not null
);
create unique index if not exists skills_name on skills (team_id, name);

-- level 3: a bundled file is read on demand and never enters a slice
create table if not exists skill_files (
  id text primary key,
  skill_id text not null references skills(id) on delete cascade,
  path text not null,
  content text not null default '',
  bytes integer not null default 0,
  created_date double precision not null
);
create unique index if not exists skill_files_path on skill_files (skill_id, path);

create table if not exists lessons (
    id text primary key,
    team_id text not null,
    agent_id text not null references agents(id) on delete cascade,
    run_id text not null default '',
    task_id text not null default '',
    statement text not null,
    status text not null default 'proposed',
    write_as text not null default '',
    actor text not null default 'agent',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists lessons_agent on lessons (agent_id, status);

-- a fan-out closes on a record: an explicit partition map, a join rule, a deadline and
-- the reports. "three of five lanes answered" and "all five answered" must not look alike.
create table if not exists convergences (
    id text primary key,
    team_id text not null,
    task_id text not null references tasks(id) on delete cascade,
    parent text not null default '',
    join_rule text not null default 'all',
    quorum integer,
    deadline double precision,
    partitions text not null default '{}',
    reports text not null default '[]',
    status text not null default 'open',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists convergences_task on convergences (task_id, status);

-- the watchdog's answers, kept as rows: a snooze is a decision with an end, a dismissal
-- is a decision with a reason, and both are attributable. an unanswered silence is
-- recorded by its absence, which is the only honest way to record silence.
create table if not exists silence_decisions (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    task_id text not null references tasks(id) on delete cascade,
    decision text not null,
    snoozed_until double precision,
    reason text not null default '',
    actor text not null default 'owner',
    recovery_task_id text not null default '',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists silence_decisions_task on silence_decisions (task_id, created_date);

-- a handoff is the atomic unit of delegation: state crosses the boundary, a summary
-- does not, so an offer carries a reference and a precondition and never a paragraph.
create table if not exists delegations (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    task_id text not null default '',
    from_agent_id text not null,
    to_agent_id text not null,
    payload_ref text not null,
    precondition text not null,
    acceptance_required integer not null default 1,
    timeout_seconds double precision not null default 3600,
    state text not null default 'offered',
    note text not null default '',
    offered_at double precision not null,
    accepted_at double precision,
    reason text not null default '',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists delegations_team on delegations (team_id, state, created_date);
create index if not exists delegations_to on delegations (to_agent_id, state);

-- a project is the unit above a card: a phase, a gate over rows, and kill criteria
-- declared before the sunk cost exists.
create table if not exists projects (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    name text not null,
    phase text not null default 'inception',
    started_at double precision not null,
    phase_started_at double precision not null,
    objective_ref text not null default '',
    slices text not null default '[]',
    unit_cost_ceiling_cents integer not null default 0,
    unit_price_cents integer,
    min_margin_pct double precision,
    kill_criteria text not null default '[]',
    closed_reason text not null default '',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists projects_team on projects (team_id, phase);

-- a claim is the unit of discourse: a fact needs evidence, a plan may not be stated as
-- a fact, and a synthesis has to account for every claim it was given.
create table if not exists claims (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    thread text not null,
    message_id text not null default '',
    kind text not null default 'inference',
    statement text not null,
    evidence text not null default '',
    confidence double precision not null default 0.5,
    basis text not null default '',
    by_agent text not null default '',
    opposes text not null default '[]',
    created_date double precision not null
);
create index if not exists claims_thread on claims (team_id, thread, created_date);

-- a limit nothing counts is a wish: one row per refusal, so "why is this seat frozen"
-- is a query.
create table if not exists strikes (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    agent_id text not null references agents(id) on delete cascade,
    code text not null default '',
    tool text not null default '',
    note text not null default '',
    cleared_by text not null default '',
    created_date double precision not null
);
create index if not exists strikes_agent on strikes (agent_id, cleared_by);

-- a wall is only a wall if the crossing is declared: direction, kinds, rate, expiry.
create table if not exists crossings (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    from_scope text not null,
    to_scope text not null,
    kinds text not null default '[]',
    max_per_hour integer not null default 0,
    max_bytes integer,
    expires_at double precision not null,
    authorized_by text not null default '',
    reason text not null default '',
    revoke_mode text not null default 'drain',
    enabled integer not null default 1,
    tokens double precision not null default 0,
    last_refill_at double precision not null,
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists crossings_pair on crossings (team_id, from_scope, to_scope);

-- an objective is a metric with a baseline, a target and a deadline. replenishment reads it
-- against the clock, so being behind is a comparison rather than a mood.
create table if not exists objectives (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    name text not null,
    baseline double precision not null,
    target double precision not null,
    deadline double precision not null,
    observed_since double precision,
    kinds text not null default '[]',
    wip_limit integer not null default 2,
    status text not null default 'active',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists objectives_team on objectives (team_id, status);

-- a measurement is an observation from outside. the first one starts the period, because
-- measuring from the latest makes every objective look ahead of itself.
create table if not exists measurements (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    objective_id text not null references objectives(id) on delete cascade,
    value double precision not null,
    computed_at double precision not null
);
create index if not exists measurements_objective on measurements (objective_id, computed_at);

-- budget as a reservation: the check and the claim are the same act, so two parallel
-- cards cannot both read the same under-budget number and both proceed.
create table if not exists budget_reservations (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    task_id text not null default '',
    run_id text not null default '',
    agent_id text not null default '',
    amount_cents double precision not null,
    currency text not null default 'usd',
    state text not null default 'held',
    reason text not null default '',
    settled_cents double precision,
    over_spend integer not null default 0,
    created_date double precision not null,
    settled_at double precision,
    updated_date double precision not null
);
create index if not exists budget_reservations_team on budget_reservations (team_id, state, created_date);

-- an eval: a grid of scenarios and candidates, one deterministic scorer, one row per
-- cell. the grid is stored with the run so a report can still be read after the code
-- that produced it has moved on.
create table if not exists eval_runs (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    name text not null default '',
    scenarios text not null default '[]',
    candidates text not null default '[]',
    scorer text not null default '{}',
    status text not null default 'draft',
    summary text not null default '{}',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists eval_runs_team on eval_runs (team_id, created_date);

create table if not exists eval_cases (
    id text primary key,
    eval_id text not null references eval_runs(id) on delete cascade,
    scenario_id text not null,
    candidate_id text not null,
    output text not null default '',
    score double precision not null default 0,
    detail text not null default '',
    created_date double precision not null
);
create index if not exists eval_cases_eval on eval_cases (eval_id, candidate_id);

-- the curated knowledge base: what would take time to explain again, and what a
-- capable agent would not already know from context.
create table if not exists knowledge_entries (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    agent_id text not null default '',
    kind text not null,
    title text not null,
    body text not null,
    symptom text not null default '',
    workaround text not null default '',
    tags text not null default '[]',
    source text not null default '',
    status text not null default 'active',
    created_date double precision not null,
    updated_date double precision not null
);
create unique index if not exists knowledge_title on knowledge_entries (team_id, kind, title);

-- intent: what a crew is for, written down, versioned, and read back into every run.
-- a task is what to do; an intent is why, and what would make the doing wrong.
create table if not exists intents (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    agent_id text not null default '',
    kind text not null default 'direction',
    statement text not null,
    rationale text not null default '',
    status text not null default 'active',
    version integer not null default 1,
    supersedes text not null default '',
    actor text not null default 'human',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists intents_team on intents (team_id, status);

-- routines: the recurring work a crew does on a cadence, with a row per day it was
-- due. schedules enqueue a job; a routine is a promise that leaves a trace when kept
-- and a miss when not, which is the difference between recurring and repeated.
create table if not exists routines (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    agent_id text not null default '',
    name text not null,
    description text not null default '',
    cadence text not null default 'daily',
    weekday integer not null default 0,
    hour integer not null default 8,
    steps text not null default '[]',
    required_skills text not null default '[]',
    status text not null default 'active',
    created_date double precision not null,
    updated_date double precision not null
);
create unique index if not exists routines_name on routines (team_id, name);

create table if not exists routine_runs (
    id text primary key,
    routine_id text not null references routines(id) on delete cascade,
    team_id text not null,
    on_date text not null,
    status text not null default 'open',
    task_id text not null default '',
    notes text not null default '',
    created_date double precision not null,
    updated_date double precision not null
);
create unique index if not exists routine_runs_day on routine_runs (routine_id, on_date);
